3: struct SearchResultGroup: Identifiable {
4:     let id: String
5:     var versions: [SearchResultItem]
6: 
7:     var primaryItem: SearchResultItem {
8:         versions.first(where: { $0.resultLanguage == "he" || $0.resultLanguage == nil })
9:             ?? versions[0]
10:     }
11: }
12: 
13: struct SearchResultsListView: View {
14:     var results: [SearchResultItem] = []
15:     var showsBookTitle: Bool = true
16:     var isLoadingMore: Bool = false
17:     var hasMore: Bool = false
18:     var automaticallyLoadsMore: Bool = true
19:     var onLoadMore: (() -> Void)? = nil
20:     var onSearchInBook: ((SearchResultItem) -> Void)? = nil
21:     var query: String = ""
22:     var mode: SearchMode = .phrase
23:     var nearDistance: Int = 10
24:     let onSelect: (SearchResultItem) -> Void
25: 
26:     @State private var expandedResultIDs: Set<String> = []
27:     @State private var selectedVersionIndex: [String: Int] = [:]
28: 
29:     private var keywords: [String] {
30:         FtsQueryParser.extractKeywords(query: query, mode: mode)
31:     }
32: 
33:     private var groupedResults: [SearchResultGroup] {
34:         var groups: [SearchResultGroup] = []
35:         var indexByKey: [String: Int] = [:]
36: 
37:         for item in results {
38:             let key = canonicalKey(for: item)
39:             if let idx = indexByKey[key] {
40:                 if !groups[idx].versions.contains(where: { $0.stableID == item.stableID }) {
41:                     groups[idx].versions.append(item)
42:                 }
43:             } else {
44:                 indexByKey[key] = groups.count
45:                 groups.append(SearchResultGroup(id: key, versions: [item]))
46:             }
47:         }
48:         return groups
49:     }
50: 
51:     private func canonicalKey(for item: SearchResultItem) -> String {
52:         if let locator = item.backendLocator {
53:             return locator.persistenceKey
54:         }
55:         return "\(item.archive):\(item.tableName):\(item.bookId):\(item.part):\(item.page)"
56:     }
57: 
58:     var body: some View {
59:         List {
60:             let groups = groupedResults
61:             ForEach(Array(groups.enumerated()), id: \.element.id) { index, group in
62:                 let activeIdx = selectedVersionIndex[group.id] ?? 0
63:                 let item = group.versions.indices.contains(activeIdx) ? group.versions[activeIdx] : group.primaryItem
64:                 let isExpanded = expandedResultIDs.contains(group.id)
65: 
66:                 VStack(alignment: .leading, spacing: 0) {
67:                     Button {
68:                         withAnimation(.snappy(duration: 0.28, extraBounce: 0)) {
69:                             if expandedResultIDs.remove(group.id) == nil {
70:                                 expandedResultIDs.insert(group.id)
71:                             }
72:                         }
73:                     } label: {
74:                         HStack(alignment: .top, spacing: 10) {
75:                             SearchResultRow(
76:                                 item: item,
77:                                 showsBookTitle: showsBookTitle,
78:                                 isExpanded: isExpanded,
79:                                 versionCount: group.versions.count,
80:                                 selectedVersionIndex: Binding(
81:                                     get: { selectedVersionIndex[group.id] ?? 0 },
82:                                     set: { selectedVersionIndex[group.id] = $0 }
83:                                 ),
84:                                 versions: group.versions,
85:                                 keywords: keywords,
86:                                 mode: mode,
87:                                 nearDistance: nearDistance
88:                             )
89:                             Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
90:                                 .font(.caption.weight(.semibold))
91:                                 .foregroundStyle(.secondary)
92:                                 .padding(.top, 4)
93:                         }
94:                     }
95:                     .buttonStyle(.plain)
96:                     .accessibilityLabel(String(localized: "Preview full search result"))
97:                     .accessibilityValue(isExpanded ? "Expanded" : "Collapsed")
98:                     .accessibilityIdentifier("search-result-preview-toggle-\(item.stableID)")
99: 
100:                     if isExpanded {
101:                         SearchResultContextPreview(item: item) {
102:                             onSelect(item)
103:                         }
104:                         .id(item.stableID)
105:                         .transition(.opacity.combined(with: .move(edge: .top)))
106:                     }
107:                 }
108:                 .contextMenu {
109:                     Button(String(localized: "Open", defaultValue: "פתח"), systemImage: "book") { onSelect(item) }
110:                     Button(String(localized: "Copy", defaultValue: "העתק"), systemImage: "doc.on.doc") {
111:                         #if canImport(UIKit)
112:                         UIPasteboard.general.string = item.attributedText.string
113:                         #endif
114:                     }
115:                     Button(String(localized: "Copy with source", defaultValue: "העתק עם מקור"), systemImage: "text.quote") {
116:                         let source = item.bookTitle
117:                         let body = item.attributedText.string
118:                         let combined = [body, source].filter { !$0.isEmpty }.joined(separator: "\n")
119:                         #if canImport(UIKit)
120:                         UIPasteboard.general.string = combined
121:                         #endif
122:                     }
123:                     if let onSearchInBook {
124:                         Button(String(localized: "Search in this book", defaultValue: "חפש בספר זה"), systemImage: "magnifyingglass") {
125:                             onSearchInBook(item)
126:                         }
127:                     }
128:                 }
129:                 .listRowBackground(Color.appBackground)
130:                 .listRowSeparator(.visible)
131:                 .listRowInsets(EdgeInsets(top: 8, leading: 16, bottom: 8, trailing: 16))
132:                 .id(group.id)
133:                 .onAppear {
134:                     if automaticallyLoadsMore, index == groups.count - 5, hasMore, !isLoadingMore {
135:                         onLoadMore?()
136:                     }
137:                 }
138:             }
139: 
140:             if isLoadingMore {
141:                 HStack {
142:                     Spacer()
143:                     ProgressView()
144:                         .padding(.vertical, 8)
145:                     Spacer()
146:                 }
147:                 .listRowBackground(Color.appBackground)
148:                 .listRowSeparator(.hidden)
149:             } else if hasMore {
150:                 Button(action: { onLoadMore?() }) {
151:                     HStack {
152:                         Spacer()
153:                         Text("Load more results", comment: "Load more search results button")
154:                             .font(.subheadline)
155:                             .foregroundStyle(Color.accentColor)
156:                             .padding(.vertical, 8)
157:                         Spacer()
158:                     }
159:                 }
160:                 .buttonStyle(.plain)
161:                 .listRowBackground(Color.appBackground)
162:                 .listRowSeparator(.hidden)
163:             }
164:         }
165:         .listStyle(.plain)
166:         .scrollContentBackground(.hidden)
167:         .background(Color.appBackground)
168:     }
169: }
